import static org.jlinalg.cli.Monocle131ModelRequest.*;

/** Typed original FastMNN execution and independent complete low-rank checking. */
public final class FastMnn129WorkflowCli {
    private FastMnn129WorkflowCli() { }
    private static final String RESOURCE="/org/jlinalg/omics/fastmnn129/";
    static final String SCOPE="Original Batchelor1.29.0 fastMNN on complete caller-prepared log-expression or signed asinh-protein matrices, with explicit batch order, restrictions/weights/feature selection, linear or tree merges, PCA and original nearest-neighbor correction. This is a selected source candidate for P040's literal method version1.29, not a recovered paper patch/call. FACTORS preserves the original complete lazy LowRankMatrix model and compares every seed-factor value with rotation/corrected coordinates; it does not numerically materialize the reconstruction. ALL_VALUES additionally checks every streamed reconstructed value with compensated native crossproducts. Neither mode refits MNN or establishes biological correctness. Reconstructed expression is intended for visualization; differential testing on corrected values, library-size normalization, raw-count/asinh/log conversion, marker selection and Rphenograph annotation are separate analyses. Requested original cosine normalization remains part of fastMNN.";
    static final String ACTION="Required action: use the documented exact private Linux R4.5.3/Batchelor1.29.0 profile, complete TSV or Matrix Market data, literal feature/cell metadata and NEW output. Provision exact dependencies only where installation/download/execution is permitted. SKIP3 skips dependent analysis if required runtime or execution is unavailable/forbidden. FAIL2 admits no result: retain complete inputs, WARNINGS.md, original logs and any unadmitted RDS; correct the named input, source, numeric, timeout or capacity cause and retry NEW paths. Preserve original errors; never replace fastMNN with reducedMNN, repair identifiers/values, infer paper settings or treat protein signals as RNA counts. A portable audit checks supplied matrix consistency only; it authenticates no producer and admits no original analysis.";
    private static final class Skipped extends IOException {private static final long serialVersionUID=1L;Skipped(String message){super(message);}}

    public static void main(String[] args){int code=run(args,System.out,System.err);if(code!=0)System.exit(code);}
    public static int run(String[] args,PrintStream stdout,PrintStream stderr){
        Path out=null;boolean owned=false,admitted=false;String cause="FAIL2: Invalid request",originalWarnings="",reconstructionMode="not-run";int code=2;
        try{
            if(args.length==1&&args[0].equals("--help")){stdout.println("fastmnn129-workflow --request UTF8_JSON\nfastmnn129-workflow --audit-result SAVED_WORKER_RESULT_JSON --out NEW_DIRECTORY [--maximum-native-operations N] [--maximum-table-bytes N]\nSchema1, version1.29.0; matrix, cells, features, format TSV|MATRIX_MARKET, input_units prepared-log-expression|prepared-asinh-protein, input_provenance, analysis_population, batch_order, seed, parameters, reconstruction_audit FACTORS(default)|ALL_VALUES, execution_policy ALLOW|FORBID, rscript, r_libraries, source_root, out and declared capacities. Feature metadata: feature_id/feature_name. Cell metadata: cell_id/batch. Signed prepared protein inputs are supported; no transformation is applied. Streaming audits read all sibling factor tables and, in ALL_VALUES mode, reconstructed-cells.tsv; retain that source directory.\n"+SCOPE+"\n"+ACTION);return 0;}
            if(args.length>=4&&args.length<=8&&args.length%2==0&&args[0].equals("--audit-result")&&args[2].equals("--out")){
                long auditOperations=1000000000,tableBytes=137438953472L;var flags=new HashSet<String>();for(int i=4;i<args.length;i+=2){require(flags.add(args[i])&&Set.of("--maximum-native-operations","--maximum-table-bytes").contains(args[i]),"Unknown/duplicate audit capacity flag");require(args[i+1].matches("[1-9][0-9]*"),"Require a positive exact audit capacity");long value=Long.parseLong(args[i+1]);if(args[i].equals("--maximum-native-operations")){require(value<=1000000000000L,"Audit operation capacity exceeds hard bound");auditOperations=value;}else{require(value<=137438953472L,"Audit table byte capacity exceeds hard bound");tableBytes=value;}}
                Path input=Path.of(args[1]).toAbsolutePath().normalize();out=Path.of(args[3]).toAbsolutePath().normalize();newOutput(out,List.of(input));owned=true;var pin=NextflowFiles.pin(input,268435456,()->{});byte[] raw=NextflowFiles.bytes(input,268435456);require(pin.equals(new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw))),"Saved result changed during capture");Files.write(out.resolve("supplied-result.json"),raw,StandardOpenOption.CREATE_NEW);var m=object(NextflowParameters.parse(NextflowFiles.utf8(raw),268435456,20000000));var audit=m.containsKey("schema_version")?FastMnn129StreamAudit.audit(m,input.getParent(),auditOperations,tableBytes):FastMnn129Audit.audit(m,auditOperations);reconstructionMode=m.containsKey("schema_version")?text(m.get("reconstruction_audit")):"LEGACY_ALL_VALUES";NextflowFiles.writeJson(out.resolve("native-audit.json"),audit);same(input,pin);cause="PASS_NATIVE_SUPPLIED_FASTMNN_MATRIX_CONSISTENCY_ONLY";code=0;
            }else{
                require(args.length==2&&args[0].equals("--request"),"Require --request JSON, --audit-result PATH --out NEW or --help");
                Path request=Path.of(args[1]).toAbsolutePath().normalize();var requestPin=NextflowFiles.pin(request,1048576,()->{});byte[] raw=NextflowFiles.bytes(request,1048576);require(requestPin.equals(new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw))),"Request changed during capture");var m=object(NextflowParameters.parse(NextflowFiles.utf8(raw),1048576,100000));var r=FastMnn129Request.parse(m,request.getParent());reconstructionMode=r.reconstructionAudit();out=r.out();var paths=new ArrayList<>(List.of(request,r.matrix(),r.cells(),r.features(),r.rscript(),r.source()));paths.addAll(r.libraries());newOutput(out,paths);owned=true;Files.write(out.resolve("source-request.json"),raw,StandardOpenOption.CREATE_NEW);
                if(!r.execute())throw new Skipped("Declared execution FORBID; no original process launched");
                if(!System.getProperty("os.name").equals("Linux"))throw new Skipped("Original FastMNN requires Linux Java; permitted WSL with Linux paths is supported");
                if(!Files.isExecutable(r.rscript()))throw new Skipped("Missing permitted profiled Rscript: "+r.rscript());
                for(Path p:r.libraries())if(!Files.isDirectory(p))throw new Skipped("Missing declared R library: "+p);
                if(!Files.isDirectory(r.source()))throw new Skipped("Missing pristine Batchelor1.29.0 source tree");
                var profile=object(NextflowParameters.parse(NextflowFiles.utf8(resource("source-profile.json")),1048576,200000));
                var source=NextflowFiles.tree(r.source(),4096,67108864,16777216,()->{});var expected=object(profile.get("source_members"));require(source.keySet().equals(expected.keySet()),"Complete pristine original source population differs; compiler working trees are separate");
                Path captured=Files.createDirectory(out.resolve("source"));
                for(var e:source.entrySet()){require(e.getValue().kind().equals("file")&&e.getValue().pin().equals(NextflowFiles.fingerprint(expected.get(e.getKey()),16777216)),"Original source differs: "+e.getKey());Path p=captured.resolve(e.getKey());Files.createDirectories(p.getParent());Files.copy(r.source().resolve(e.getKey()),p);same(p,e.getValue().pin());}
                Files.createDirectory(out.resolve("inputs"));var inputs=new LinkedHashMap<Path,NextflowFiles.Pin>();long total=0;
                for(var e:Map.of("matrix.data",r.matrix(),"cells.tsv",r.cells(),"features.tsv",r.features()).entrySet()){var p=NextflowFiles.pin(e.getValue(),r.inputBytes(),()->{});total=Math.addExact(total,p.bytes());require(total<=r.inputBytes(),"Complete input byte capacity exceeded");inputs.put(e.getValue(),p);Files.copy(e.getValue(),out.resolve("inputs").resolve(e.getKey()));same(out.resolve("inputs").resolve(e.getKey()),p);}
                var population=FastMnn129Inputs.read(out.resolve("inputs/matrix.data"),out.resolve("inputs/cells.tsv"),out.resolve("inputs/features.tsv"),r.format(),r.units(),r.batches(),r.entries());
                var batchValues=population.batches();
                require(new HashSet<>(batchValues).equals(new HashSet<>(r.batches())),"Every declared batch must occur in the complete input");
                for(String key:List.of("subset_features","restrict_cells"))if(r.parameters().get(key)!=null){var labels=NextflowFiles.strings(r.parameters().get(key));require((key.equals("subset_features")?population.features():population.cells()).containsAll(labels),"Unknown literal "+key+" label; no repair or substitution");}
                var runtime=new LinkedHashMap<Path,Map<String,NextflowFiles.Entry>>();
                for(String name:object(profile.get("package_versions")).keySet())for(Path library:r.libraries()){Path path=library.resolve(name);if(Files.isDirectory(path)){runtime.put(path,NextflowFiles.tree(path,8192,536870912,134217728,()->{}));break;}}
                var rscriptPin=NextflowFiles.pin(r.rscript(),33554432,()->{});
                Files.write(out.resolve("worker.R"),resource("worker.R"),StandardOpenOption.CREATE_NEW);Files.write(out.resolve("source-profile.json"),resource("source-profile.json"),StandardOpenOption.CREATE_NEW);
                var worker=new LinkedHashMap<String,Object>();worker.put("format",r.format());worker.put("input_units",r.units());worker.put("input_provenance",text(m.get("input_provenance")));worker.put("analysis_population",text(m.get("analysis_population")));worker.put("batch_order",r.batches());worker.put("parameters",r.parameters());worker.put("reconstruction_audit",r.reconstructionAudit());NextflowFiles.writeJson(out.resolve("worker-request.json"),worker);
                var rows=new LinkedHashMap<String,Object>();for(var e:runtime.entrySet())rows.put(e.getKey().toString(),NextflowFiles.manifest(e.getValue()));NextflowFiles.writeJson(out.resolve("runtime-provenance.json"),Map.of("rscript",r.rscript().toString(),"rscript_pin",rscriptPin,"libraries",r.libraries().stream().map(Path::toString).toList(),"runtime_packages",rows,"producer_authenticated",false));
                Path bundle=out;var before=NextflowFiles.tree(out,20000,r.outputBytes(),r.outputBytes(),()->{});var inputStamps=new LinkedHashMap<Path,Stamp>();for(Path input:inputs.keySet())inputStamps.put(input,stamp(input));for(String name:List.of("matrix.data","cells.tsv","features.tsv")){Path p=out.resolve("inputs").resolve(name);inputStamps.put(p,stamp(p));}
                NextflowProcess.Check integrity=()->{same(request,requestPin);for(var e:inputStamps.entrySet())require(e.getValue().equals(stamp(e.getKey())),"Input file identity/size/timestamp changed during analysis");same(r.rscript(),rscriptPin);require(NextflowFiles.tree(r.source(),4096,67108864,16777216,()->{}).equals(source),"Original source changed during analysis");for(var e:before.entrySet())if(e.getValue().kind().equals("file")&&!e.getKey().startsWith("inputs/"))same(bundle.resolve(e.getKey()),e.getValue().pin());};
                var prefix=r.rscript().getParent().getParent();var env=new LinkedHashMap<String,String>();env.put("PATH",prefix.resolve("bin")+":/usr/bin:/bin");env.put("R_HOME",prefix.resolve("lib/R").toString());env.put("LD_LIBRARY_PATH",prefix.resolve("lib").toString());env.put("R_ENVIRON_USER","/dev/null");env.put("R_PROFILE_USER","/dev/null");env.put("LANG","C.UTF-8");env.put("LC_ALL","C.UTF-8");for(String key:List.of("OMP_NUM_THREADS","OPENBLAS_NUM_THREADS","MKL_NUM_THREADS"))env.put(key,"1");var command=new ArrayList<>(List.of(r.rscript().toString(),"--vanilla",out.resolve("worker.R").toString(),out.toString()));command.addAll(r.libraries().stream().map(Path::toString).toList());
                try{NfcoreProcess.executeSession(command,env,out.resolve("process"),out,out,new NextflowProcess.Limits(r.seconds()*1000L,r.addressSpace(),r.seconds(),r.outputBytes(),1024,r.outputBytes(),20000,128,256,r.rss(),200),integrity,()->{});}catch(IOException e){String detail=Files.isRegularFile(out.resolve("worker-error.txt"))?NextflowFiles.utf8(NextflowFiles.bytes(out.resolve("worker-error.txt"),65536)).strip():e.toString();if(Files.isRegularFile(out.resolve("worker-failure.json"))){var failure=read(out.resolve("worker-failure.json"),r.jsonBytes());originalWarnings="\n\n## Original/adapter failure warnings\n\n"+String.join("\n\n",NextflowFiles.strings(failure.get("warnings")));}if(Files.isRegularFile(out.resolve("worker-exit.txt"))&&Files.readString(out.resolve("worker-exit.txt")).strip().equals("3"))throw new Skipped("Profiled original runtime unavailable: "+detail);throw new IOException("Original fastMNN failed: "+detail+"; retain complete diagnostics and any unadmitted fit",e);}
                integrity.verify();for(var e:inputs.entrySet())same(e.getKey(),e.getValue());for(var e:before.entrySet())if(e.getValue().kind().equals("file")&&e.getKey().startsWith("inputs/"))same(bundle.resolve(e.getKey()),e.getValue().pin());for(var e:runtime.entrySet())require(NextflowFiles.tree(e.getKey(),8192,536870912,134217728,()->{}).equals(e.getValue()),"Original runtime package changed during analysis: "+e.getKey());
                var result=read(out.resolve("worker-result.json"),r.jsonBytes());require(NextflowFiles.strings(result.get("cell_ids")).equals(population.cells())&&NextflowFiles.strings(result.get("batches")).equals(batchValues),"Original complete cell/batch axes differ");
                var selected=r.parameters().get("subset_features");var features=selected==null||bool(r.parameters().get("correct_all"))?population.features():NextflowFiles.strings(selected);require(NextflowFiles.strings(result.get("feature_ids")).equals(features),"Original complete selected-feature population differs");require(text(result.get("input_units")).equals(r.units()),"Original unit/provenance context differs");
                require(text(result.get("reconstruction_audit")).equals(r.reconstructionAudit()),"Original/native reconstruction mode differs");var audit=FastMnn129StreamAudit.audit(result,out,r.operations(),r.outputBytes());
                for(String name:List.of("original-fit.rds","metadata.rds"))require(NextflowFiles.pin(out.resolve(name),r.outputBytes(),()->{}).bytes()>0,"Missing complete original model/metadata");NextflowFiles.writeJson(out.resolve("native-audit.json"),audit);var warnings=NextflowFiles.strings(result.get("warnings"));originalWarnings="\n\n## Original/adapter warnings ("+warnings.size()+")\n\n"+(warnings.isEmpty()?"None returned.":String.join("\n\n",warnings));integrity.verify();admitted=true;cause="PASS_ORIGINAL_FASTMNN129_PREPARED_BATCH_CORRECTION_AND_NATIVE_RECONSTRUCTION_CHECK";code=0;
            }
        }catch(Skipped|NextflowProcess.Unavailable e){cause="SKIP3: "+e;code=3;}catch(Exception e){cause="FAIL2: "+e;code=2;}catch(OutOfMemoryError e){cause="FAIL2: Java heap exhausted; no partial result admitted";code=2;}
        if(code!=0)admitted=false;
        try{if(owned){Files.writeString(out.resolve("WARNINGS.md"),"# "+cause+"\n\n"+SCOPE+"\n\nReconstruction audit: "+reconstructionMode+". FACTORS checks every model/seed factor and retains the complete lazy original assay; it does not assert numerical finiteness or agreement of unmaterialized reconstructed entries. ALL_VALUES additionally materializes and checks every reconstructed entry as cells-by-features TSV. No original result is admitted by a portable audit.\n\nLarge captured inputs use file identity/size/timestamp monitoring during execution, with full content hashes before and after; this does not authenticate a producer.\n\n"+ACTION+originalWarnings+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(out.resolve("analysis-status.json"),Map.of("status",cause,"exit_code",code,"result_admitted",admitted,"reconstruction_audit",reconstructionMode,"required_action",ACTION,"producer_authenticated",false,"paper_patch_recovered",false,"whole_tool_qualified",false,"whole_goal_complete",false));}}catch(IOException e){cause="FAIL2: Cannot write complete warnings/status: "+e;code=2;}
        (code==0?stdout:stderr).println(cause+(out==null?"":"\nOutput: "+out));stderr.println("WARNINGS / "+ACTION);return code;
    }

    private static void checkTable(Path file,String first,List<String> rows,List<String> columns,Object value)throws IOException {
        var expected=list(value);require(expected.size()==rows.size(),"Incomplete native table reference");try(var reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){String header=reader.readLine();require(header!=null,"Missing complete original table header");var names=header.split("\t",-1);require(names[0].equals(first),"Original table axis header differs");if(columns!=null)require(Arrays.asList(names).subList(1,names.length).equals(columns),"Original table column population differs");for(int i=0;i<rows.size();i++){String line=reader.readLine();require(line!=null,"Incomplete original table rows");var fields=line.split("\t",-1);var target=list(expected.get(i));require(fields.length==target.size()+1&&fields.length==names.length&&fields[0].equals(rows.get(i)),"Original table row/column population differs");for(int j=0;j<target.size();j++)require(fields[j+1].equals(text(target.get(j))),"Original TSV/JSON numeric token differs");}require(reader.readLine()==null,"Excess original table rows");}
    }
    private static Map<String,Object> read(Path p,int max)throws IOException{return object(NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(p,max)),max,20000000));}
    private static byte[] resource(String name)throws IOException{try(var in=FastMnn129WorkflowCli.class.getResourceAsStream(RESOURCE+name)){if(in==null)throw new IOException("Missing packaged worker/profile: "+name);return in.readAllBytes();}}
    private record Stamp(long bytes,FileTime modified,Object key) { }
    private static Stamp stamp(Path path)throws IOException{var a=Files.readAttributes(path,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);require(a.isRegularFile(),"Input is no longer a regular file");return new Stamp(a.size(),a.lastModifiedTime(),a.fileKey());}
    private static void same(Path p,NextflowFiles.Pin wanted)throws IOException{require(wanted.equals(NextflowFiles.pin(p,wanted.bytes(),()->{})),"Captured input/source/runtime changed: "+p);}
    private static void newOutput(Path out,List<Path> protectedPaths)throws IOException{require(!Files.exists(out,LinkOption.NOFOLLOW_LINKS),"Output must be NEW; retain prior evidence");NextflowFiles.directory(out.getParent());for(Path p:protectedPaths)require(!out.startsWith(p)&&!p.startsWith(out),"Output overlaps protected input/source/runtime");Files.createDirectory(out);}
}
